"use client";

import {cn} from "cn";

/**
 * A site's brand mark (an SVG string from its `brand/mark.ts`), inlined. Size it in multiples of 32px
 * (default `size-8`) so it stays pixel-sharp (GUIDELINES §7b).
 */
export function BrandMark({svg, className}: {svg: string; className?: string}) {
    return (
        <span
            aria-hidden
            className={cn("inline-block size-8 shrink-0 leading-0", className)}
            // Static markup generated by the site from its own mark shapes, never from user input.
            dangerouslySetInnerHTML={{__html: svg}}
        />
    );
}

export interface BrandLogoProps {
    /** The mark's SVG markup. */
    svg: string;
    /** The wordmark's first word, in the foreground ("Kernel"). */
    first: string;
    /** Its second word, in the accent text tier ("Kit"). */
    second: string;
    className?: string;
}

/** Mark + two-tone wordmark in mono semibold: Kernel**Kit**, Termi**Color** (the suite's brand pattern). */
export function BrandLogo({svg, first, second, className}: BrandLogoProps) {
    return (
        <span className={cn("inline-flex items-center gap-2", className)}>
            <BrandMark svg={svg} />
            <span className="font-mono text-sm font-semibold tracking-tight">
                {first}
                <span className="text-primary-text">{second}</span>
            </span>
        </span>
    );
}
